async function getMgaRgaDetails(userEmail2) {
  if (!supabaseAdmin) {
    console.error("\u274C Supabase admin client not initialized");
    return { isMgaRga: false };
  }
  try {
    const { data: customer } = await supabaseAdmin.from("customers").select("associate_id").eq("company_email", userEmail2.toLowerCase().trim()).maybeSingle();
    if (!customer?.associate_id) {
      return { isMgaRga: false };
    }
    const { data: mgaRga } = await supabaseAdmin.from("mga_rga_directory").select("associate_id, name, role").eq("associate_id", customer.associate_id).maybeSingle();
    if (mgaRga) {
      return {
        isMgaRga: true,
        role: mgaRga.role,
        name: mgaRga.name,
        associateId: mgaRga.associate_id
      };
    }
    return { isMgaRga: false };
  } catch (error) {
    console.error(`\u274C Error in getMgaRgaDetails for ${userEmail2}:`, error);
    return { isMgaRga: false };
  }
}
