      /**
       * Assign leads to a specific agent based on territory and market matching
       */
      async assignLeadsToAgent(agentEmail, licensedStates, market, count5) {
        try {
          if (!supabaseAdmin) return 0;
          const currentCallable = await countCallableLeads(supabaseAdmin, agentEmail.toLowerCase());
          const { data: customerForAssociate } = await supabaseAdmin.from("customers").select("associate_id").or(`company_email.eq.${agentEmail.toLowerCase()},personal_email.eq.${agentEmail.toLowerCase()}`).maybeSingle();
          const associateId2 = customerForAssociate?.associate_id?.toString() || "999";
          const webhookPayload = {
            agentEmail: agentEmail.toLowerCase(),
            associate_id: associateId2,
            requestedCount: count5,
            currentCount: currentCallable,
            markets: market ? [market] : [],
            // Include markets for lead matching (convert string to array)
            states: licensedStates || [],
            // Include states for lead matching
            source: "lead_assignment_scheduler"
          };
          try {
            const webhookResult = await fetch("https://aointelleadsync-production.up.railway.app/api/ccpro/assignment-trigger", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify(webhookPayload),
              signal: AbortSignal.timeout(1e4)
              // 10 second timeout
            });
            if (webhookResult.ok) {
              const webhookResponse = await webhookResult.json();
              const assignedCount = webhookResponse.assigned || 0;
              if (assignedCount === 0) {
                console.log(`\u26A0\uFE0F No available leads for ${agentEmail}`);
              } else {
                console.log(`\u{1F4CB} Webhook sent: ${assignedCount} leads requested for ${agentEmail}`);
              }
              return assignedCount;
            } else {
              const errorText = await webhookResult.text();
              console.error(`\u274C Webhook failed for ${agentEmail}: HTTP ${webhookResult.status}: ${errorText}`);
              return 0;
            }
          } catch (webhookError) {
            console.error(`\u274C Error sending webhook for ${agentEmail}:`, webhookError);
            return 0;
          }
        } catch (error) {
          console.error(`\u274C Error in assignLeadsToAgent for ${agentEmail}:`, error);
          return 0;
        }
      }
