              supabaseAdmin.from("masterlead").select("*", { count: "exact", head: true }).eq("cn_email", agentEmail).eq("cnresolution", "pending").eq("dnc", false).not("taalk_market", "in", "(Plus Lead,Plus Leads,plus lead,plus leads)"),
              supabaseAdmin.from("masterlead").select("*", { count: "exact", head: true }).eq("cn_email", agentEmail).eq("cnresolution", "called").eq("dnc", false).not("taalk_market", "in", "(Plus Lead,Plus Leads,plus lead,plus leads)"),
              supabaseAdmin.from("masterlead").select("*", { count: "exact", head: true }).eq("cn_email", agentEmail).in("cnresolution", ["no_answer_vm", "no_answer"]).eq("dnc", false).not("taalk_market", "in", "(Plus Lead,Plus Leads,plus lead,plus leads)")
