  app2.post("/api/agent-message", async (req, res) => {
    try {
      const { roomId, message, agentName } = req.body;
      if (!roomId || !message) {
        return res.status(400).json({
          success: false,
          error: "roomId and message are required"
        });
      }
      console.log(`\u{1F4E2} Agent ${agentName || "Unknown"} sending message to room ${roomId}: ${message}`);
      const messageData = {
        type: "agent_message",
        roomId: roomId.trim(),
        message: message.trim(),
        agentName: agentName || "Agent",
        timestamp: (/* @__PURE__ */ new Date()).toISOString()
      };
      if (videoWebSocketServer && videoWebSocketServer.clients) {
        let messagesSent = 0;
        videoWebSocketServer.clients.forEach((client2) => {
          if (client2.readyState === 1) {
            try {
              client2.send(JSON.stringify(messageData));
              messagesSent++;
            } catch (error) {
              console.error("Error sending message to WebSocket client:", error);
            }
          }
        });
        console.log(`\u2705 Agent message sent to ${messagesSent} WebSocket clients`);
      } else {
        console.log("\u26A0\uFE0F WebSocket server not available, message stored for later delivery");
      }
      res.json({
        success: true,
        message: "Agent message queued for delivery",
        roomId: roomId.trim(),
        agentName: agentName || "Agent"
      });
    } catch (error) {
      console.error("\u274C Failed to send agent message:", error);
      res.status(500).json({
        success: false,
        error: "Failed to send agent message",
        details: error instanceof Error ? error.message : "Unknown error"
      });
    }
  });
  app2.get("/api/notifications", async (req, res) => {
    try {
      const sessionUser = req.session.user;
      const headerEmail = req.headers["user-email"] || req.headers["x-user-email"];
      let agentEmail = null;
      if (sessionUser?.email) {
        agentEmail = sessionUser.email.toLowerCase();
        console.log("\u{1F514} /api/notifications - Using session email:", agentEmail);
      } else if (headerEmail) {
        agentEmail = headerEmail.toLowerCase();
        console.log("\u{1F514} /api/notifications - Using header email:", agentEmail);
      }
      if (!agentEmail) {
        console.log("\u274C /api/notifications - No authentication found (session or header)");
        return res.status(401).json({ error: "Not authenticated" });
      }
      console.log("\u{1F514} /api/notifications - Fetching for:", agentEmail);
      const limit = parseInt(req.query.limit) || 50;
      const unreadOnly = req.query.unreadOnly === "true";
      let query = supabaseAdmin.from("agent_notifications").select("*").eq("agent_email", agentEmail).order("created_at", { ascending: false }).limit(limit);
      if (unreadOnly) {
        query = query.eq("read", false);
      }
      const { data: notifications, error } = await query;
      if (error) {
        console.error("\u274C Error fetching notifications:", error);
        return res.status(500).json({ error: "Failed to fetch notifications" });
      }
      const allNotifications = notifications || [];
      console.log("\u{1F514} /api/notifications - Found", allNotifications.length, "notifications for", agentEmail);
      const { data: allUnreadNotifications } = await supabaseAdmin.from("agent_notifications").select("*").eq("agent_email", agentEmail).eq("read", false);
      const unreadCount = (allUnreadNotifications || []).length;
      console.log("\u{1F514} /api/notifications - Unread count:", unreadCount);
      res.json({
        notifications: allNotifications,
        unreadCount: unreadCount || 0
      });
    } catch (error) {
      console.error("Error in /api/notifications:", error);
      res.status(500).json({ error: "Internal server error" });
    }
  });
